if (want_text) total_cost_cents += state.cfg.credit_contents_per_page_cents;
if (want_highlights) total_cost_cents += state.cfg.credit_highlights_per_page_cents;
if (want_summary) total_cost_cents += state.cfg.credit_summary_per_page_cents;
